func VersionInfo(pVersionInfo *VersionInfoStruct) error {
	if err := checkLibSym("dcgmVersionInfo"); err != nil {
		return err
	}
	return toError(fnVersionInfo(pVersionInfo), "dcgmVersionInfo")
}

// WatchFields requests that DCGM start recording updates for a given field collection.
//
// Note that the first update of the field will not occur until the next field update cycle.
// To force a field update cycle, call [Handle.UpdateAllFields](1).
//
//   - pDcgmHandle: IN: DCGM Handle
//   - groupId: IN: Group ID representing collection of one or more entities. Look at [Handle.GroupCreate] for details on creating the group. Alternatively, pass in the group id as [GroupAllGPUs] to perform operation on all the GPUs or [GroupAllNvSwitches] to to perform the operation on all NvSwitches
//   - fieldGroupId: IN: Fields to watch
//   - updateFreq: IN: How often to update this field in usec
//   - maxKeepAge: IN: How long to keep data for this field in seconds
//   - maxKeepSamples: IN: Maximum number of samples to keep. 0=no limit
//
// Wraps dcgmWatchFields.
func WatchFields(pDcgmHandle Handle, groupId GpuGrp, fieldGroupId FieldGrp, updateFreq int64, maxKeepAge float64, maxKeepSamples int32) error {
	if err := checkLibSym("dcgmWatchFields"); err != nil {
		return err
	}
	return toError(fnWatchFields(pDcgmHandle, groupId, fieldGroupId, updateFreq, maxKeepAge, maxKeepSamples), "dcgmWatchFields")
}
